  /* Çözüm adımları: 🔎 anla → 💡 hatırla → ✏️ adımlar → ✅ sonuç → 🔁 kontrol */
  const cz = (anla, hatir, adimlar, sonuc, kontrol) => ["🔎 Soruyu anlayalım: " + anla, "💡 Hatırlayalım: " + hatir].concat(adimlar.map(a => "✏️ " + a), ["✅ Sonuç: " + sonuc, "🔁 " + kontrol]);
  /* Zaman şeridi: olaylar [[tarih, "olay"], ...] eşit aralıklı; olay metni iki satıra bölünebilir ("|" ile) */
  function seritt(olaylar, baslik) {
    const n = olaylar.length, W = 620, H = 170, sol = 50, sag = 570, y = 70;
    const xk = i => n === 1 ? (sol + sag) / 2 : sol + i * (sag - sol) / (n - 1);
    let ic = (baslik ? G.yazi(W / 2, 20, baslik, { b: 1 }) : "") + G.ok(20, y, 605, y);
    olaylar.forEach(([t, m], i) => {
      ic += `<circle class="g-a" cx="${xk(i)}" cy="${y}" r="8"/>` + G.yazi(xk(i), y - 16, t, { b: 1 });
      String(m).split("|").forEach((s, j) => { ic += G.yazi(xk(i), y + 30 + j * 16, s, { k: 1 }); });
    });
    return G.svg(W, H, ic, "zaman şeridi: " + olaylar.map(o => o[0] + " " + String(o[1]).replace(/\|/g, " ")).join(", "));
  }

